import Foundation

func llfsmFail(_ message: String, code: Int32) -> Never {
    FileHandle.standardError.write(Data((message + "\n").utf8))
    exit(code)
}

func llfsmCheck(_ value: Swift.Int, _ lower: Swift.Int, _ upper: Swift.Int, _ name: String) -> Swift.Int {
    if value < lower || value > upper {
        llfsmFail("range violation \(name)", code: 2)
    }
    return value
}

func llfsmIndex(_ index: Swift.Int, _ size: Swift.Int, _ name: String) -> Swift.Int {
    llfsmCheck(index, 0, size - 1, name)
}

enum Side: Swift.Int, CaseIterable {
    case `left`, `right`
}

func llfsmParse_Side(_ text: String) -> Side? {
    Side.allCases.first { "\($0)" == text }
}

typealias Count = Swift.Int

func llfsmParse_Count(_ text: String) -> Count? {
    guard let value = Swift.Int(text), value >= 0, value <= 9 else {
        return nil
    }
    return value
}

enum Relay_State: Swift.Int, CaseIterable {
    case `Waiting`, `Holding`, `Passing`

    static let llfsmAccepting: [Swift.Bool] = [false, false, false]
    static let llfsmPassThrough: [Swift.Bool] = [false, false, true]
}

final class Relay_Machine {
    var llfsmState: Relay_State = .`Waiting`
    var llfsmEntered = true
    var me: Side = Side.`left`
    var passes: Count = 0
}

final class LLFSMArrangement {
    var turn: Side = Side.`left`
    let llfsmInstance_leftHand = Relay_Machine()
    let llfsmInstance_rightHand = Relay_Machine()

    func llfsmInitialise() {
        turn = Side.`left`
        llfsmInstance_leftHand.me = Side.`left`
        llfsmInstance_rightHand.me = Side.`right`
    }

    func llfsmRinglet_Relay(_ llfsmMachine: Relay_Machine) {
        var me: Side {
            get { llfsmMachine.me }
            set { llfsmMachine.me = newValue }
        }
        var passes: Count {
            get { llfsmMachine.passes }
            set { llfsmMachine.passes = newValue }
        }
        while true {
            if llfsmMachine.llfsmEntered {
                llfsmMachine.llfsmEntered = false
                if llfsmMachine.llfsmState == Relay_State.`Holding` {
                    print("holding", me, passes)
                }
                if llfsmMachine.llfsmState == Relay_State.`Passing` {
                    turn = ((me == Side.`left`) ? Side.`right` : Side.`left`)
                    passes = llfsmCheck((passes + 1), 0, 9, "passes")
                }
            }
            var llfsmNext: Relay_State?
            if llfsmMachine.llfsmState == Relay_State.`Waiting` {
                if (turn == me) {
                    llfsmNext = .`Holding`
                }
            }
            if llfsmMachine.llfsmState == Relay_State.`Holding` {
                if (passes < 9) {
                    llfsmNext = .`Passing`
                }
            }
            if llfsmMachine.llfsmState == Relay_State.`Passing` {
                if true {
                    llfsmNext = .`Waiting`
                }
            }
            guard let llfsmTarget = llfsmNext else {
                return
            }
            llfsmMachine.llfsmState = llfsmTarget
            llfsmMachine.llfsmEntered = true
            if !Relay_State.llfsmPassThrough[llfsmTarget.rawValue] {
                return
            }
        }
    }

    func llfsmSetExternal(_ key: String, _ index: Swift.Int?, _ value: String) -> Swift.Bool {
        switch key {
        default:
            return false
        }
    }

    func llfsmApplyAssignment(_ token: Substring) -> Swift.Bool {
        guard let equals = token.firstIndex(of: "=") else {
            return false
        }
        let key = token.prefix(upTo: equals)
        let value = String(token.suffix(from: token.index(after: equals)))
        var name = String(key)
        var index: Swift.Int?
        if let bracket = key.firstIndex(of: "\u{5B}") {
            let position = key.suffix(from: key.index(after: bracket))
            let digits = position.dropLast()
            let unsigned = digits.first == "+" || digits.first == "-" ? digits.dropFirst() : digits
            guard position.last == "\u{5D}", !unsigned.isEmpty, unsigned.allSatisfy({ $0 >= "0" && $0 <= "9" }),
                  let parsed = Swift.Int(digits) else {
                return false
            }
            name = String(key.prefix(upTo: bracket))
            index = parsed
        }
        return llfsmSetExternal(name, index, value)
    }

    func llfsmApplyInputs(_ lines: [String], round: Swift.Int) -> Swift.Bool {
        for line in lines {
            let tokens = line.split(whereSeparator: { $0 == " " || $0 == "\t" || $0 == "\r" })
            guard let first = tokens.first, Swift.Int(first) == round else {
                continue
            }
            for token in tokens.dropFirst() where !llfsmApplyAssignment(token) {
                FileHandle.standardError.write(Data("invalid input \(token)\n".utf8))
                return false
            }
        }
        return true
    }
}

@main
struct TurnTakingRelay {
    static func main() {
        let arguments = CommandLine.arguments
        let maxRounds = arguments.count > 1 ? (Swift.Int(arguments[1]) ?? 0) : 20
        var inputLines = Array<String>()
        if arguments.count > 2 {
            guard let text = try? String(contentsOfFile: arguments[2], encoding: .utf8) else {
                llfsmFail("cannot open \(arguments[2])", code: 1)
            }
            inputLines = text.split(separator: "\n", omittingEmptySubsequences: false).map { String($0) }
        }
        let arrangement = LLFSMArrangement()
        arrangement.llfsmInitialise()
        print("arrangement TurnTakingRelay")
        var round = 1
        while true {
            if !arrangement.llfsmApplyInputs(inputLines, round: round) {
                exit(1)
            }
            arrangement.llfsmRinglet_Relay(arrangement.llfsmInstance_leftHand)
            print("R\(round) leftHand \(arrangement.llfsmInstance_leftHand.llfsmState)")
            arrangement.llfsmRinglet_Relay(arrangement.llfsmInstance_rightHand)
            print("R\(round) rightHand \(arrangement.llfsmInstance_rightHand.llfsmState)")
            if Relay_State.llfsmAccepting[arrangement.llfsmInstance_leftHand.llfsmState.rawValue] && !arrangement.llfsmInstance_leftHand.llfsmEntered && Relay_State.llfsmAccepting[arrangement.llfsmInstance_rightHand.llfsmState.rawValue] && !arrangement.llfsmInstance_rightHand.llfsmEntered {
                print("halt R\(round)")
                break
            }
            if round == maxRounds {
                break
            }
            round += 1
        }
    }
}
